  "jLZWsPEluyQ": { title: "Better to Fight for Our Religious Rights Than to Fight for Our Democratic Rights. From the Episode with Malki Rotner.", description: "" },
  "znN60Us-2nM": { title: "You Can't Get to Know God Through Nashim and Nezikin — Rabbi Sefi Gladzahler Gives No Free Pass to the Haredi Yeshiva World", description: "" },
  "qrV0_c16tuI": { title: "Being a Haredi Mother to Soldiers. Yehudit Yifrach on How October 7th Hit Her", description: "" },
  "bd5mMvjy6pw": { title: "Haredit Meduberet | Rabbi Refael Yehonatan Polissuk | Marry a Woman and Have Something on the Side | SHORT", description: "\"Marry a woman and have something on the side\" — that's the advice Rabbi Refael Yehonatan Polissuk received about his sexual orientation.\nWhat would you have done?" },
  "IiAR-vuMqJU": { title: "Haredit Meduberet | Rabbi Refael Yehonatan Polissuk | SHORT", description: "Is it offensive that, in the name of Torah and religion, people with a certain orientation are pushed out of religion?\nRabbi Refael Yehonatan Polissuk, in a candid moment from the new episode of \"Haredit Meduberet\"" },
  "gOrQAhl3HUQ": { title: "Rabbi Refael Yehonatan Polissuk, in a Candid and Moving Moment from the New Episode of \"Haredit Meduberet\"", description: "Conversion therapy is like taking a jackhammer to the deepest floor of the soul, until the soul collapses." },
  "TBJpHkWyc1Q": { title: "\"Being Haredi in the State of Israel Basically Means Enjoying a World the Litvish Built\" | Esty Shushan Hosts Nehorai Abergel", description: "" },
  "oOfe2-fTeW4": { title: "\"Out in the World They're Called Teenagers, Here We Call Them Thugs\" | Esty Shushan Hosts Nehorai Abergel", description: "" },
  "TDOE2SaQOoA": { title: "\"Out in the World They're Called Teenagers, Here We Call Them Thugs\" | Esty Shushan Hosts Nehorai Abergel", description: "" },
  "dxP8nd_uVWA": { title: "Is There Still Exclusion of Mizrahi Yeshiva Students? | Esty Shushan Hosts Nehorai Abergel", description: "" },
  "KCdu-ABhFs0": { title: "The Heart Closes Up When the Body Lets Go | From the New Episode with Rabbi Nir Menussi", description: "The Heart Closes Up When the Body Lets Go | From the New Episode with Rabbi Nir Menussi" },
  "5-6B2-2sgeM": { title: "Happiness or Meaning? What Will You Give Yourself and Your Children?", description: "Happiness or Meaning? What Will You Give Yourself and Your Children?" },
  "RXt2SxSWITU": { title: "\"When the Community Suffocates You | Esty Shushan Hosts Dr. Shimon Azoulay\" — The New Episode Is Already Waiting for You on All Platforms, See You There!", description: "\"When the Community Suffocates You | Esty Shushan Hosts Dr. Shimon Azoulay\" — The New Episode Is Already Waiting for You on All Platforms, See You There!" },
  "qNN_IAPAKRA": { title: "\"The Gentle Man\" — Not a Term You Hear Every Day! From the Episode with Moishy Lifshitz", description: "\"The Gentle Man\" — Not a Term You Hear Every Day! From the Episode with Moishy Lifshitz" },
  "j9PqsemL3iI": { title: "It's More Fun Being a Haredi Girl | From the New Episode with Moishy Lifshitz", description: "It's More Fun Being a Haredi Girl | From the New Episode with Moishy Lifshitz" },
  "OI7_w1pQUZI": { title: "No One Comes Out Unscathed! From the Important (and Complicated) Episode with Aharon Rabinowitz", description: "No One Comes Out Unscathed! From the Important (and Complicated) Episode with Aharon Rabinowitz" },
