  "gGP1OVIUo0g": { title: "Yoav Lalum on the Lawsuit Over the Discrimination His Daughter Faced at School, and His Drive to Take the Power Back", description: "\"I want it on record that my daughter was accepted to this school — I won't let them disqualify her\" Yoav Lalum shares the story of the lawsuit over the discrimination his daughter faced at school, and his drive to take the power back! #HareditMeduberet #Haredi #podcast #EstyShushan #news #HarediEducation #talkshow" },
  "B0yZTAuxkg8": { title: "The Shame of Mrs. Yocheved's Letter! Attorney Yoav Lalum Shares His Daughter's Story — Rejected From School Over Racism!", description: "The shame of Mrs. Yocheved Eliashiv's letter! Attorney Yoav Lalum shares his personal story about his daughter, who was rejected from school due to blatant racism that they tried to cover up with lies.\nAn important, compelling episode about discrimination and racism.\nAvailable on YouTube, Spotify, and Apple Podcasts\n#Haredi #podcast #EstyShushan #HareditMeduberet #HarediEducation #Racism" },
  "XHA1xx3LhQM": { title: "Ashkenazi or Sephardi? In Matchmaking, School, and Work, It Often Feels Like Your Background Determines Your Worth. Why?!", description: "Ashkenazi or Sephardi? In matchmaking, schools, and workplaces, it often feels like your background determines your worth — your \"price.\" And the question is, why?! Attorney Yoav Lalum talks about the fight against discrimination within Haredi society" },
