  "L_bEWBjuOeU": { title: "The Fight Against Discrimination in Haredi Society Is Real, and It Matters! From the Episode With Yoav Lalum", description: "The fight against discrimination in Haredi society is real, and it matters! From the episode with Yoav Lalum\n#Haredi #podcast #EstyShushan #news #HareditMeduberet #HarediEducation #HarediWomen" },
